const isWeekend=(value:string)=>{const day=dateObject(value).getDay();return day===0||day===6};
function nearestBusinessDate(value:string,direction:-1|1=-1){const date=dateObject(value);while(date.getDay()===0||date.getDay()===6)date.setDate(date.getDate()+direction);return dateValue(date)}
