function hideTooltip(){clearTimeout(tooltipTimer);tooltipTarget=null;appTooltip.classList.remove('show')}
function placeTooltip(e:PointerEvent){const gap=14,box=appTooltip.getBoundingClientRect();let left=e.clientX+gap,top=e.clientY+gap;if(left+box.width>innerWidth-8)left=e.clientX-box.width-gap;if(top+box.height>innerHeight-8)top=e.clientY-box.height-gap;appTooltip.style.left=Math.max(8,left)+'px';appTooltip.style.top=Math.max(8,top)+'px'}
document.addEventListener('pointerover',e=>{const el=(e.target as HTMLElement).closest<HTMLElement>('.sheet [data-tooltip]');if(!el)return;const text=el.dataset.tooltip||'';if(!text)return;clearTimeout(tooltipTimer);tooltipTarget=el;appTooltip.textContent=text;placeTooltip(e);tooltipTimer=window.setTimeout(()=>{if(tooltipTarget===el)appTooltip.classList.add('show')},320)});
