async function loadReport(){const main=isMainReport();setHeader(main?'Ежедневный отчет':manager()?'Сводный отчёт':'Мой ежедневный отчёт',main?'Ежедневные показатели компаний':manager()?'Суммарные показатели сотрудников':'Заполнение персональных показателей');rememberScroll();if(manager()){adminUsers=await api<User[]>(`/api/users?context=report&date=${encodeURIComponent(reportDate)}`);if(selectedEmployee&&!adminUsers.some(user=>user.id===selectedEmployee))selectedEmployee=''}const filter=manager()&&selectedEmployee?`&employeeId=${encodeURIComponent(selectedEmployee)}`:'';report=await api(`${main?'/api/main-office/bootstrap':'/api/bootstrap'}?date=${reportDate}${filter}`);renderReport();scheduleDebtsterRefresh()}
function traineeDate(value:string|null){return value&&/^\d{4}-\d{2}-\d{2}$/.test(value)?displayDate(value):'—'}
function traineeRowClass(row:TraineeReport){
 const source=row.source.trim().toUpperCase();
 if(!Array.isArray(row.matches))return '';
 if(source==='ДИР'&&row.matches.length)return 'trainee-director-match';
 if(source==='ОК'&&row.matches.length===0)return 'trainee-ok-unmatched';
 return '';
}
function traineeSearchResults(row:TraineeReport){
 if(!Array.isArray(row.matches))return '<td class="trainee-search-result-cell">Поиск недоступен</td>';
 if(!row.matches.length)return '<td class="trainee-search-result-cell">Не найдено</td>';
 return `<td class="trainee-search-result-cell"><ul class="trainee-matches" aria-label="Возможные совпадения в нашей базе">${row.matches.map(match=>`<li><span>${esc(match.full_name)}</span><small aria-label="Сходство ФИО: ${esc(match.score)}%">${esc(match.score)}%</small></li>`).join('')}</ul></td>`;
}
