function defaultTableWidth(){return Math.max(reportColumns().length*80,Math.min(1470,content.clientWidth-24))}
function defaultColWidth(id:string){const columns=reportColumns(),index=columns.findIndex(([column])=>column===id),natural=columns.reduce<number>((sum,[column])=>sum+(defaultColumnWidths[column]||125),0),target=defaultTableWidth();if(index<0)return 125;const before=columns.slice(0,index).reduce<number>((sum,[column])=>sum+(defaultColumnWidths[column]||125),0),after=before+(defaultColumnWidths[id]||125);return Math.round(after*target/natural)-Math.round(before*target/natural)}
