function restoreScroll(){requestAnimationFrame(()=>{const el=content.querySelector<HTMLElement>('.sheet-wrap');if(!el)return;const pos=JSON.parse(sessionStorage.getItem(`hr-scroll-${reportDate}`)||'{"top":0,"left":0}');el.scrollTop=pos.top;el.scrollLeft=pos.left;el.onscroll=()=>sessionStorage.setItem(`hr-scroll-${reportDate}`,JSON.stringify({top:el.scrollTop,left:el.scrollLeft}))})}
function connectReportSocket(){if(reportSocket){const old=reportSocket;reportSocket=null;old.close()}const socketDate=reportDate,main=isMainReport(),ws=new WebSocket(`${location.protocol==='https:'?'wss':'ws'}://${location.host}/ws/reports?date=${encodeURIComponent(socketDate)}`);reportSocket=ws;ws.onmessage=e=>{const event=JSON.parse(e.data);if(event.date!==reportDate)return;if(event.type==='report_access_changed'){if(!manager()&&event.userIds?.includes(currentUser?.id))loadReport();return}if(event.type==='report_plan_changed'){const expected=main?'main_office':'rp';if(event.reportType===expected&&(manager()||event.userIds?.includes(currentUser?.id)))loadReport();return}if(event.type!==(main?'main_office_report_updated':'report_updated'))return;if(manager()){clearTimeout(reportRefreshTimer);reportRefreshTimer=window.setTimeout(()=>loadReport(),250);return}if((event.field==='openVacancies'||event.field==='plannedReserve')&&report){const index=report.rows.findIndex(r=>r.officeId===event.officeId);if(index<0)return;const row=report.rows[index],key=event.field as 'openVacancies'|'plannedReserve';row[key]=Number(event.value)||0;const input=content.querySelector<HTMLInputElement>(`tr[data-row="${index}"] input[data-key="${key}"]`);if(input){input.value=String(row[key]);input.dataset.original=input.value}recalc()}};ws.onclose=()=>{if(reportSocket===ws){reportSocket=null;if((currentPage==='report'||currentPage==='main-report')&&isMainReport()===main&&reportDate===socketDate)setTimeout(connectReportSocket,1500)}}}
function setupColumnResizing(){content.querySelectorAll<HTMLElement>('[data-resize]').forEach(handle=>handle.onpointerdown=e=>{e.preventDefault();const id=handle.dataset.resize!,col=content.querySelector<HTMLElement>(`col[data-col="${id}"]`)!,table=content.querySelector<HTMLTableElement>('.sheet')!,start=e.clientX,startWidth=col.getBoundingClientRect().width,startTableWidth=table.getBoundingClientRect().width;const move=(ev:PointerEvent)=>{const width=Math.round(Math.max(80,Math.min(320,startWidth+ev.clientX-start)));col.style.width=width+'px';table.style.width=startTableWidth+width-startWidth+'px';columnWidths[id]=width;updateResetButtonVisibility()};const up=()=>{document.removeEventListener('pointermove',move);document.removeEventListener('pointerup',up);if(hasCustomColumnWidths())localStorage.setItem('hr-column-widths-v2',JSON.stringify(columnWidths));else localStorage.removeItem('hr-column-widths-v2')};document.addEventListener('pointermove',move);document.addEventListener('pointerup',up)})}
function applyColumnWidths(){content.querySelectorAll<HTMLElement>('col[data-col]').forEach(col=>{col.style.width=colWidth(col.dataset.col!)+'px'});const table=content.querySelector<HTMLTableElement>('.sheet');if(table)table.style.width=tableWidth()+'px';alignTableWithToolbar()}
function resetColumnWidths(){columnWidths={};localStorage.removeItem('hr-column-widths-v2');applyColumnWidths();updateResetButtonVisibility()}

async function dailyPlanModal(){
 try{
  const reportType=isMainReport()?'main_office':'rp',all=await api<DailyPlan[]>(`/api/daily-plans?date=${encodeURIComponent(reportDate)}&reportType=${reportType}`),plans=selectedEmployee?all.filter(item=>item.userId===selectedEmployee):all;
  if(!plans.length){toast('Сотрудники для изменения плана не найдены',true);return}
  const rows=plans.map(item=>`<div class="daily-plan-row"><span><b>${esc(item.name)}</b><small>${item.overridden?'Планы на этот день изменены':'Используются основные планы'}</small></span><label><small>Приглашённые</small><input class="input daily-plan-input" type="number" min="0" step="1" inputmode="numeric" data-kind="invited" data-user-id="${item.userId}" data-original="${item.invitedPlan}" value="${item.invitedPlan}"></label><label><small>Принятые</small><input class="input daily-plan-input" type="number" min="0" step="1" inputmode="numeric" data-kind="hired" data-user-id="${item.userId}" data-original="${item.hiredPlan}" value="${item.hiredPlan}"></label></div>`).join('');
  showModal(`Планы на ${displayDate(reportDate)}`,`<div class="modal-intro"><b>Однодневные планы кандидатов</b><span>Изменения действуют только для выбранной даты и не меняют основные планы сотрудника.</span></div><div class="daily-plan-list">${rows}</div>`,async()=>{
   const changed=plans.filter(item=>[...document.querySelectorAll<HTMLInputElement>(`.daily-plan-input[data-user-id="${item.userId}"]`)].some(input=>input.value!==input.dataset.original)).map(item=>({userId:item.userId,invitedPlan:Number((document.querySelector(`.daily-plan-input[data-user-id="${item.userId}"][data-kind="invited"]`) as HTMLInputElement).value),hiredPlan:Number((document.querySelector(`.daily-plan-input[data-user-id="${item.userId}"][data-kind="hired"]`) as HTMLInputElement).value)}));
   if(changed.some(item=>!Number.isInteger(item.invitedPlan)||item.invitedPlan<0||!Number.isInteger(item.hiredPlan)||item.hiredPlan<0)){toast('Планы должны быть целыми неотрицательными числами',true);return}
   if(!changed.length){closeModal();return}
   await api('/api/daily-plans',{method:'PUT',body:JSON.stringify({date:reportDate,reportType,plans:changed})});closeModal();toast('План на выбранный день сохранён');await loadReport()
  })
 }catch(error){toast((error as Error).message,true)}
}

function accessFullName(user:ReportAccessUser){return [user.lastName,user.firstName,user.middleName].filter(Boolean).join(' ')}
function accessUntilLabel(value:string){return new Date(value).toLocaleString('ru-RU',{day:'numeric',month:'long',hour:'2-digit',minute:'2-digit'})}
async function reportAccessModal(){
 try{
  const users=await api<ReportAccessUser[]>(`/api/report-access?date=${encodeURIComponent(reportDate)}`),active=users.filter(user=>user.accessUntil),available=users.filter(user=>!user.accessUntil);
  const activeMarkup=active.length?`<section class="access-section"><div class="access-section-head"><b>Доступ открыт</b><span>${active.length}</span></div><div class="access-current-list">${active.map(user=>`<div class="access-current"><span class="access-avatar">${esc((user.firstName?.[0]||'')+(user.lastName?.[0]||''))}</span><span class="access-person"><b>${esc(accessFullName(user))}</b><small>До ${esc(accessUntilLabel(user.accessUntil!))}</small></span><button class="btn btn-danger close-access" type="button" data-id="${user.id}">Закрыть</button></div>`).join('')}</div></section>`:'';
  const availableMarkup=available.length?`<section class="access-section"><div class="access-section-head"><b>Выберите сотрудников</b><button class="access-select-all" type="button">Выбрать всех</button></div><div class="access-check-list">${available.map(user=>`<label class="access-check"><input type="checkbox" value="${user.id}"><span class="access-avatar">${esc((user.firstName?.[0]||'')+(user.lastName?.[0]||''))}</span><span>${esc(accessFullName(user))}</span></label>`).join('')}</div></section>`:`<div class="access-empty">Всем активным сотрудникам доступ уже открыт</div>`;
  showModal('Доступ к отчёту',`<div class="access-intro"><span class="access-date">${new Date(reportDate+'T00:00:00').toLocaleDateString('ru-RU',{day:'numeric',month:'long',year:'numeric'})}</span><p>Выбранные сотрудники смогут редактировать свой отчёт в течение 24 часов.</p></div>${activeMarkup}${availableMarkup}`,async()=>{
   const userIds=[...document.querySelectorAll<HTMLInputElement>('.access-check input:checked')].map(input=>input.value);if(!userIds.length)return;
   try{await api('/api/report-access',{method:'POST',body:JSON.stringify({date:reportDate,userIds})});closeModal();toast(`Доступ открыт на 24 часа: ${userIds.length}`);await loadReport()}catch(error){toast((error as Error).message,true)}
  },()=>{
   const save=document.querySelector<HTMLButtonElement>('.modal .save')!;save.textContent='Открыть доступ';save.disabled=true;
   const checks=[...document.querySelectorAll<HTMLInputElement>('.access-check input')],sync=()=>save.disabled=!checks.some(input=>input.checked);checks.forEach(input=>input.onchange=sync);
   const selectAll=document.querySelector<HTMLButtonElement>('.access-select-all');if(selectAll)selectAll.onclick=()=>{const allSelected=checks.every(input=>input.checked);checks.forEach(input=>input.checked=!allSelected);selectAll.textContent=allSelected?'Выбрать всех':'Снять выбор';sync()};
   document.querySelectorAll<HTMLButtonElement>('.close-access').forEach(button=>button.onclick=async()=>{button.disabled=true;try{await api('/api/report-access',{method:'DELETE',body:JSON.stringify({date:reportDate,userIds:[button.dataset.id]})});closeModal();toast('Доступ закрыт');await loadReport()}catch(error){button.disabled=false;toast((error as Error).message,true)}});
   if(!available.length)save.hidden=true;
  });
 }catch(error){toast((error as Error).message,true)}
}

async function responsiblesModal(row:Row,cell:HTMLButtonElement){
 try{
  const reportType=isMainReport()?'main_office':'rp',users=await api<ResponsibleUser[]>(`/api/report-responsibles?date=${encodeURIComponent(reportDate)}&reportType=${reportType}&unitId=${encodeURIComponent(row.officeId)}`),assigned=users.filter(user=>user.assigned).length,unitLabel=isMainReport()?'компанию ГО':'РП';
  const active=users.filter(user=>user.assigned),periods=new Set(active.map(user=>`${user.assignedFrom||''}|${user.assignedTo||''}`)),commonPeriod=active.length>0&&periods.size===1?active[0]:undefined;
  const initialScope=commonPeriod&&!commonPeriod.assignedTo?'forever':commonPeriod?.assignedFrom===reportDate&&commonPeriod?.assignedTo===reportDate?'today':commonPeriod?'period':'today';
  const defaultEndDate=dateValue(new Date(dateObject(reportDate).getTime()+6*86400000)),endDate=commonPeriod?.assignedTo&&commonPeriod.assignedTo>=reportDate?commonPeriod.assignedTo:defaultEndDate;
  const checked=(value:string)=>initialScope===value?'checked':'';
  const periodLabel=(user:ResponsibleUser)=>!user.assignedFrom?'':!user.assignedTo?`С ${displayDate(user.assignedFrom)} без ограничения срока`:user.assignedFrom===user.assignedTo?`На ${displayDate(user.assignedFrom)}`:`${displayDate(user.assignedFrom)} — ${displayDate(user.assignedTo)}`;
  const scope=`<section class="assignment-scope"><div class="assignment-scope-head"><b>Срок назначения</b><span>С какой периодичностью действует доступ</span></div><div class="assignment-scope-options" role="radiogroup" aria-label="Срок назначения"><label class="assignment-scope-option"><input type="radio" name="responsible-scope" value="today" ${checked('today')}><span><b>На этот день</b><small>${displayDate(reportDate)}</small></span></label><label class="assignment-scope-option"><input type="radio" name="responsible-scope" value="period" ${checked('period')}><span><b>На период</b><small>Указать дату окончания</small></span></label><label class="assignment-scope-option"><input type="radio" name="responsible-scope" value="forever" ${checked('forever')}><span><b>Навсегда</b><small>Начиная с этой даты</small></span></label></div><div class="assignment-period" hidden><div class="field"><label>С даты</label><input class="input" type="date" value="${reportDate}" disabled></div><span>—</span><div class="field"><label>По дату</label><input id="responsible-end-date" class="input" type="date" min="${reportDate}" value="${endDate}"></div></div><div class="assignment-scope-summary" aria-live="polite"></div></section>`;
  const list=users.length?`<section class="access-section"><div class="access-section-head"><b>Сотрудники <span class="assignment-selected-count">${assigned}</span></b><button class="access-select-all" type="button">${assigned===users.length?'Снять выбор':'Выбрать всех'}</button></div><div class="access-check-list">${users.map(user=>`<label class="access-check"><input type="checkbox" value="${user.id}" ${user.assigned?'checked':''}><span class="access-avatar">${esc((user.firstName?.[0]||'')+(user.lastName?.[0]||''))}</span><span class="access-person"><b>${esc(accessFullName(user))}</b>${user.assigned?`<small>${esc(periodLabel(user))}</small>`:''}</span></label>`).join('')}</div></section>`:'<div class="access-empty">Нет активных сотрудников для назначения</div>';
  showModal(`Назначенные · ${row.officeName}`,`<div class="access-intro assignment-intro"><span class="access-date">${esc(row.officeName)}</span><p>Выберите сотрудников, которые смогут заполнять ${unitLabel}, и задайте срок назначения.</p></div>${scope}${list}`,async()=>{
   const userIds=[...document.querySelectorAll<HTMLInputElement>('.access-check input:checked')].map(input=>input.value);
   const scope=(document.querySelector<HTMLInputElement>('input[name="responsible-scope"]:checked'))!.value,endDate=(document.querySelector<HTMLInputElement>('#responsible-end-date'))?.value||'';
   if(scope==='period'&&(!endDate||endDate<reportDate)){toast('Дата окончания должна быть не раньше даты начала',true);return}
   const scopeLabel=scope==='today'?`на ${displayDate(reportDate)}`:scope==='period'?`на период ${displayDate(reportDate)} — ${displayDate(endDate)}`:`с ${displayDate(reportDate)} без ограничения срока`;
   try{await api('/api/report-responsibles',{method:'PUT',body:JSON.stringify({date:reportDate,endDate,scope,reportType,unitId:row.officeId,userIds})});row.responsibleCount=userIds.length;cell.textContent=String(userIds.length);closeModal();toast(`Назначения ${scopeLabel} сохранены: ${userIds.length}`)}catch(error){toast((error as Error).message,true)}
  },()=>{
   const checks=[...document.querySelectorAll<HTMLInputElement>('.access-check input')],selectAll=document.querySelector<HTMLButtonElement>('.access-select-all'),count=document.querySelector<HTMLElement>('.assignment-selected-count'),period=document.querySelector<HTMLElement>('.assignment-period')!,summary=document.querySelector<HTMLElement>('.assignment-scope-summary')!,end=document.querySelector<HTMLInputElement>('#responsible-end-date')!;
   const syncSelection=()=>{const selected=checks.filter(input=>input.checked).length;if(count)count.textContent=String(selected);if(selectAll)selectAll.textContent=selected===checks.length&&checks.length?'Снять выбор':'Выбрать всех'};
   const syncScope=()=>{const value=document.querySelector<HTMLInputElement>('input[name="responsible-scope"]:checked')!.value;period.hidden=value!=='period';summary.textContent=value==='today'?`Назначение действует только ${displayDate(reportDate)}.`:value==='period'?`Назначение действует с ${displayDate(reportDate)} по ${displayDate(end.value)} включительно.`:`Назначение действует с ${displayDate(reportDate)} без даты окончания.`};
   checks.forEach(input=>input.onchange=syncSelection);if(selectAll)selectAll.onclick=()=>{const allSelected=checks.length>0&&checks.every(input=>input.checked);checks.forEach(input=>input.checked=!allSelected);syncSelection()};
   document.querySelectorAll<HTMLInputElement>('input[name="responsible-scope"]').forEach(input=>input.onchange=syncScope);end.onchange=syncScope;syncSelection();syncScope();
  });
 }catch(error){toast((error as Error).message,true)}
}

