function peopleSummaryModal(r:Row,key:PeopleKey){const config=peopleFields[key],details=r.peopleDetails?.[config.category]||[],groups=new Map<string,string[]>(),initials=(name:string)=>name.split(/\s+/).filter(Boolean).slice(0,2).map(part=>part[0]).join('').toUpperCase()||'?';details.forEach(x=>{const owner=x.responsible||'Сотрудник не указан';groups.set(owner,[...(groups.get(owner)||[]),x.fullName])});const total=details.length||Number(r[key]||0),overview=`<div class="summary-count"><div class="summary-count-copy"><b>${esc(config.itemTitle)}</b><span>Всего по выбранн${isMainReport()?'ой компании':'ому РП'}</span></div><div class="summary-total"><b>${total}</b><span>чел.</span></div></div>`;let body='';if(groups.size){body=`${overview}<div class="hired-summary">${[...groups].map(([owner,names])=>`<section class="hired-group"><div class="hired-owner"><span class="owner-avatar">${esc(initials(owner))}</span><div class="owner-meta"><small>Заполнил список ФИО</small><b>${esc(owner)}</b></div><span class="owner-count"><b>${names.length}</b><span>чел.</span></span></div><div class="hired-list-title">${esc(config.action)}</div><ol class="hired-names">${names.map((name,index)=>`<li><span class="hire-number">${index+1}</span><span class="hire-name">${esc(name)}</span></li>`).join('')}</ol></section>`).join('')}</div>`}else{const contributions=(r.contributions?.[key]||[]).filter(x=>x.value>0);body=contributions.length?`${overview}<div class="hired-summary">${contributions.map(x=>`<section class="hired-group"><div class="hired-owner"><span class="owner-avatar">${esc(initials(x.name))}</span><div class="owner-meta"><small>Данные без списка ФИО</small><b>${esc(x.name)}</b></div><span class="owner-count"><b>${x.value}</b><span>чел.</span></span></div></section>`).join('')}</div>`:`<div class="modal-empty">В этом списке пока никого нет</div>`}showInfoModal(`${config.itemTitle} · ${r.officeName}`,body)}
function plannedDismissalsModal(r:Row){const people=r.plannedDismissals||[],overview=`<div class="summary-count"><div class="summary-count-copy"><b>Планируемый резерв</b><span>Сотрудники с планируемым увольнением · данные Debtster только для просмотра</span></div><div class="summary-total"><b>${Number(r.plannedDismissalsCount||0)}</b><span>чел.</span></div></div>`,list=people.length?`<div class="hired-summary"><section class="hired-group"><div class="hired-list-title">Список сотрудников</div><ol class="hired-names">${people.map((person,index)=>{const name=[person.last_name,person.first_name,person.middle_name].filter(Boolean).join(' ');return `<li><span class="hire-number">${index+1}</span><span class="hire-name">${esc(name)}</span></li>`}).join('')}</ol></section></div>`:`<div class="modal-empty">Debtster не вернул список сотрудников</div>`;showInfoModal(`Планируемый резерв · ${r.officeName}`,overview+list)}
function peopleModal(r:Row,tr:HTMLTableRowElement,key:PeopleKey){const config=peopleFields[key];r.people||={};let names=r.people[config.category]?.length?[...r.people[config.category]!]:[''];const body=()=>`<div class="modal-intro"><b>${esc(config.itemTitle)}</b><span>Укажите полное ФИО каждого человека</span></div><div id="hire-list">${names.map((name,index)=>`<div class="hire-row people-row"><span class="hire-index">${index+1}</span><input class="input hire-input" data-i="${index}" value="${esc(name)}" placeholder="Фамилия Имя Отчество"><button class="remove-hire" data-i="${index}" aria-label="Удалить">×</button></div>`).join('')}</div><button id="add-hire" class="add-row-button">+ Добавить</button>`;showModal(config.title,body(),async()=>{names=[...document.querySelectorAll<HTMLInputElement>('.hire-input')].map(input=>input.value.trim()).filter(Boolean);r.people[config.category]=names;r[key]=names.length;tr.querySelector<HTMLButtonElement>(`.people-list[data-people-key="${key}"]`)!.textContent=String(names.length);updateEfficiencyCells(r,tr);recalc();await saveNow(r,tr)},wire);function wire(){document.querySelector<HTMLButtonElement>('#add-hire')!.onclick=()=>{names=[...document.querySelectorAll<HTMLInputElement>('.hire-input')].map(input=>input.value);names.push('');document.querySelector('.modal-body')!.innerHTML=body();wire();requestAnimationFrame(()=>{const inputs=document.querySelectorAll<HTMLInputElement>('.hire-input');inputs[inputs.length-1]?.focus()})};document.querySelectorAll<HTMLButtonElement>('.remove-hire').forEach(button=>button.onclick=()=>{names=[...document.querySelectorAll<HTMLInputElement>('.hire-input')].map(input=>input.value);names.splice(Number(button.dataset.i),1);if(!names.length)names=[''];document.querySelector('.modal-body')!.innerHTML=body();wire()})}}
async function saveNow(r:Row,tr:HTMLTableRowElement){setSaveState('saving');try{const x=await api<{efficiency:number;invitationEfficiency:number;hiringEfficiency:number}>(`${isMainReport()?'/api/main-office/report/rows':'/api/report/rows'}/${r.id}`,{method:'PUT',body:JSON.stringify(rowPayload(r))});r.efficiency=x.efficiency;r.invitationEfficiency=x.invitationEfficiency;r.hiringEfficiency=x.hiringEfficiency;updateEfficiencyCells(r,tr);dirtyRows.delete(r.id);setSaveState(dirtyRows.size?'saving':'saved');closeModal();toast('Сохранено')}catch(e){setSaveState('failed');toast((e as Error).message,true)}}

function showModal(name:string,body:string,onSave:()=>void|Promise<void>,after?:()=>void){closeModal();modalRoot.innerHTML=`<div class="modal-backdrop"><div class="modal" role="dialog" aria-modal="true" aria-label="${esc(name)}"><div class="modal-head"><h2>${esc(name)}</h2><button class="close" aria-label="Закрыть">×</button></div><div class="modal-body">${body}</div><div class="modal-foot"><span class="modal-hint">Esc — закрыть · Ctrl+Enter — сохранить</span><button class="btn btn-outline cancel">Отмена</button><button class="btn btn-primary save">Сохранить</button></div></div></div>`;modalRoot.querySelectorAll<HTMLElement>('.close,.cancel').forEach(x=>x.onclick=closeModal);const save=modalRoot.querySelector<HTMLButtonElement>('.save')!;save.onclick=()=>onSave();modalKeyHandler=e=>{if(e.key==='Escape'){e.preventDefault();closeModal()}else if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();save.click()}};document.addEventListener('keydown',modalKeyHandler);after?.();requestAnimationFrame(()=>modalRoot.querySelector<HTMLElement>('input,textarea,button,select')?.focus())}
function showInfoModal(name:string,body:string){closeModal();modalRoot.innerHTML=`<div class="modal-backdrop"><div class="modal summary-modal" role="dialog" aria-modal="true" aria-label="${esc(name)}"><div class="modal-head"><h2>${esc(name)}</h2><button class="close" aria-label="Закрыть">×</button></div><div class="modal-body">${body}</div><div class="modal-foot"><button class="btn btn-primary close-info">Закрыть</button></div></div></div>`;modalRoot.querySelectorAll<HTMLElement>('.close,.close-info').forEach(x=>x.onclick=closeModal);modalKeyHandler=e=>{if(e.key==='Escape'){e.preventDefault();closeModal()}};document.addEventListener('keydown',modalKeyHandler)}
function closeModal(){if(modalKeyHandler){document.removeEventListener('keydown',modalKeyHandler);modalKeyHandler=null}modalRoot.innerHTML=''}
function download(url:string){location.href=url}

const correctionStatus:{[key:string]:string}={pending:'Ожидает решения',approved:'Одобрен',rejected:'Отклонён'};
const correctionReportType:{[key:string]:string}={rp:'Региональные подразделения',main_office:'Головной офис'};
const correctionPeopleFields:{category:PeopleCategory;label:string}[]=[{category:'invited_candidates',label:'Приглашённые кандидаты'},{category:'interviewed_candidates',label:'Прошедшие собеседование'},{category:'interns',label:'Кандидаты на стажировке'},{category:'reserve_candidates',label:'Кандидаты в резерве'},{category:'dismissed_workers',label:'Уволенные работники'}];

function correctionDateTime(value:string){return new Date(value).toLocaleString('ru-RU',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'})}
function previousBusinessDay(){const date=dateObject(today());do{date.setDate(date.getDate()-1)}while(date.getDay()===0||date.getDay()===6);return dateValue(date)}
function correctionStatusBadge(request:CorrectionRequest){return `<span class="correction-status ${request.status}"><i></i>${correctionStatus[request.status]}</span>`}
function correctionCount(values:CorrectionValues,category:PeopleCategory|'hired_workers'){return category==='hired_workers'?values.hiredWorkers.length:(values.people[category]||[]).length}
type CorrectionDraftWorker=HiredWorker&{origin?:number};
type CandidateCorrectionDiff={kind:'added'|'removed'|'changed';before?:HiredWorker;after?:HiredWorker};
function candidateCorrectionDiffs(before:HiredWorker[],after:HiredWorker[]):CandidateCorrectionDiff[]{
 // Match unchanged records first, including duplicates and reordered names.
 const remaining=after.map(worker=>({...worker})),removed:HiredWorker[]=[];
 before.forEach(worker=>{const index=remaining.findIndex(next=>next.fullName===worker.fullName&&next.position===worker.position);if(index>=0)remaining.splice(index,1);else removed.push(worker)});
 const result:CandidateCorrectionDiff[]=[];
 // A retained name with a different position is an explicit position change.
 const unmatched:HiredWorker[]=[];
 removed.forEach(worker=>{const index=remaining.findIndex(next=>next.fullName===worker.fullName);if(index>=0)result.push({kind:'changed',before:worker,after:remaining.splice(index,1)[0]});else unmatched.push(worker)});
 // Display replacement blocks as before/after; snapshots do not contain person IDs.

 unmatched.forEach(worker=>result.push({kind:'removed',before:worker}));remaining.forEach(worker=>result.push({kind:'added',after:worker}));
 return result
}
function correctionCandidateGroups(change:CorrectionChange){
 if(change.edits?.length){return [...correctionPeopleFields,{category:'hired_workers',label:'Принятые работники'}].map(field=>({label:field.label,diffs:change.edits!.filter(edit=>edit.category===field.category)})).filter(group=>group.diffs.length)}
 const groups=correctionPeopleFields.map(field=>({label:field.label,diffs:candidateCorrectionDiffs((change.before.people[field.category]||[]).map(fullName=>({fullName,position:''})),(change.after.people[field.category]||[]).map(fullName=>({fullName,position:''})))}));
 groups.push({label:'Принятые работники',diffs:candidateCorrectionDiffs(change.before.hiredWorkers,change.after.hiredWorkers)});
 return groups.filter(group=>group.diffs.length)
}
function correctionCandidateDetails(change:CorrectionChange){
 const person=(worker:HiredWorker)=>`<b>${esc(worker.fullName)}</b>${worker.position?`<span>${esc(worker.position)}</span>`:''}`;
 return correctionCandidateGroups(change).map(group=>`<div class="candidate-diff-group"><h4>${esc(group.label)}</h4>${group.diffs.map(diff=>`<div class="candidate-diff ${diff.kind}"><span class="candidate-diff-label">${diff.kind==='added'?'Добавление':diff.kind==='removed'?'Удаление':'Было → станет'}</span><div class="candidate-diff-values">${diff.before?`<div class="candidate-before"><small>Было</small>${person(diff.before)}</div>`:''}${diff.before&&diff.after?'<span class="candidate-diff-arrow" aria-hidden="true">→</span>':''}${diff.after?`<div class="candidate-after"><small>${diff.kind==='added'?'Новая запись':'Станет'}</small>${person(diff.after)}</div>`:''}</div></div>`).join('')}</div>`).join('')
}
function correctionChangeCount(request:CorrectionRequest){return request.changes.reduce((total,change)=>total+correctionCandidateGroups(change).reduce((count,group)=>count+group.diffs.length,0)+Number(change.before.openVacancies!==change.after.openVacancies)+Number(change.before.plannedReserve!==change.after.plannedReserve),0)}
function correctionDiffs(change:CorrectionChange){
 const diffs:{label:string;before:number;after:number}[]=[];
 correctionPeopleFields.forEach(field=>{const before=correctionCount(change.before,field.category),after=correctionCount(change.after,field.category);if(before!==after)diffs.push({label:field.label,before,after})});
 const beforeHires=correctionCount(change.before,'hired_workers'),afterHires=correctionCount(change.after,'hired_workers');if(beforeHires!==afterHires)diffs.push({label:'Принятые работники',before:beforeHires,after:afterHires});
 if(change.before.openVacancies!==change.after.openVacancies)diffs.unshift({label:'Открытые вакансии',before:change.before.openVacancies,after:change.after.openVacancies});
 if(change.before.plannedReserve!==change.after.plannedReserve)diffs.push({label:'Планируемый резерв',before:change.before.plannedReserve,after:change.after.plannedReserve});
 return diffs
}
function correctionSummary(request:CorrectionRequest){const total=correctionChangeCount(request);return `${request.changes.length} ${request.changes.length===1?'подразделение':'подразделения'} · ${total} ${total===1?'изменение':'изменений'}`}

async function correctionRequestsPage(){
 const requests=await api<CorrectionRequest[]>('/api/correction-requests');
 if(manager())renderCorrectionAdmin(requests);else renderCorrectionEmployee(requests)
}

function correctionStats(requests:CorrectionRequest[]){
 const count=(status:CorrectionRequest['status'])=>requests.filter(request=>request.status===status).length;
 return `<div class="correction-stats"><div><span>Ожидают</span><b>${count('pending')}</b></div><div><span>Одобрено</span><b>${count('approved')}</b></div><div><span>Отклонено</span><b>${count('rejected')}</b></div></div>`
}

function renderCorrectionEmployee(requests:CorrectionRequest[]){
 setHeader('Запросы на корректировку','Изменения отчётов за прошедшие дни');
 const rows=requests.map(request=>`<article class="correction-item employee-request"><div class="correction-date"><small>${esc(correctionReportType[request.reportType])}</small><b>${displayDate(request.reportDate)}</b></div><div class="correction-copy"><div>${correctionStatusBadge(request)}<span class="correction-created">Отправлен ${correctionDateTime(request.createdAt)}</span></div><p>${esc(request.note||"Без примечания")}</p><small class="correction-request-summary">${esc(correctionSummary(request))}</small>${request.reviewNote?`<div class="correction-review"><b>Комментарий администратора</b><span>${esc(request.reviewNote)}</span></div>`:''}${request.status==='approved'?'<small class="correction-applied">✓ Изменения внесены в отчёт</small>':''}</div><div class="correction-actions"><button class="btn btn-outline view-correction" data-id="${request.id}">Изменения</button></div></article>`).join('');
 content.innerHTML=`<div class="correction-page"><section class="correction-hero"><div class="correction-hero-icon">${icons.correction}</div><div><h2>Нужно исправить запись?</h2><p>Откройте отчёт за нужный день, нажмите на ячейку со списком и нажмите «Запросить корректировку».</p></div><button id="new-correction-request" class="btn btn-primary">Открыть отчёт</button></section>${correctionStats(requests)}<section class="correction-list-head"><div><h3>Мои запросы</h3><span>Отправленные изменения и решения администратора</span></div></section><div class="correction-list">${rows||'<div class="correction-empty">Запросов пока нет</div>'}</div></div>`;
 document.querySelector<HTMLButtonElement>('#new-correction-request')!.onclick=showCorrectionRequestModal;
 document.querySelectorAll<HTMLButtonElement>('.view-correction').forEach(button=>button.onclick=()=>showCorrectionDetails(requests.find(request=>request.id===button.dataset.id)!))
}

function canRequestCellCorrection(row:Row){return currentUser?.role==='employee'&&reportDate<today()&&!isWeekend(reportDate)&&(isMainReport()||row.assigned===true)}
function showCellCorrectionList(row:Row,key:PeopleKey|'hires',resume?:()=>void){
 const label=key==='hires'?'Принятые работники':peopleFields[key].itemTitle;
 const workers=key==='hires'?row.hiredWorkers:(row.people[peopleFields[key].category]||[]).map(fullName=>({fullName,position:''}));
 const overview=`<div class="summary-count"><div class="summary-count-copy"><b>${esc(label)}</b><span>${displayDate(reportDate)} · Сохранённые записи</span></div><div class="summary-total"><b>${workers.length}</b><span>чел.</span></div></div>`;
 const list=workers.length?`<div class="hired-summary"><section class="hired-group"><div class="hired-list-title">Список сотрудников</div><ol class="hired-names">${workers.map((worker,i)=>`<li><span class="hire-number">${i+1}</span><span class="hire-person"><span class="hire-name">${esc(worker.fullName)}</span>${worker.position?`<small>${esc(worker.position)}</small>`:''}</span></li>`).join('')}</ol></section></div>`:'<div class="modal-empty">В этом списке пока никого нет</div>';
 showInfoModal(`${label} · ${row.officeName}`,overview+list);
 const button=document.createElement('button');button.className='btn btn-primary';button.id='request-cell-correction';button.textContent=resume?'Продолжить корректировку':'Запросить корректировку';button.onclick=resume||(()=>showCellCorrectionEditor(row,key));
 modalRoot.querySelector('.close-info')!.className='btn btn-outline close-info';modalRoot.querySelector('.modal-foot')!.append(button)
}
function showCellCorrectionEditor(row:Row,key:PeopleKey|'hires',draft?:{workers:CorrectionDraftWorker[];note:string;baseline:CorrectionValues}){
 const date=reportDate,reportType=isMainReport()?'main_office':'rp',label=key==='hires'?'Принятые работники':peopleFields[key].itemTitle;
 const baseline=draft?.baseline||JSON.parse(JSON.stringify(rowPayload(row))) as CorrectionValues;
 let workers:CorrectionDraftWorker[]=draft?.workers||(key==='hires'?baseline.hiredWorkers.map((worker,origin)=>({...worker,origin})):(baseline.people[peopleFields[key].category]||[]).map((fullName,origin)=>({fullName,position:'',origin})));
 let note=draft?.note||'',sending=false;
 const read=()=>{workers=[...modalRoot.querySelectorAll<HTMLElement>('.hire-row')].map((el,i)=>({origin:workers[i]?.origin,fullName:el.querySelector<HTMLInputElement>('.hire-input')!.value,position:el.querySelector<HTMLInputElement>('.hire-position')?.value||''}));note=modalRoot.querySelector<HTMLTextAreaElement>('#cell-correction-note')!.value};
 const body=()=>`<div class="correction-form"><div class="modal-intro"><b>${esc(label)} · ${esc(row.officeName)}</b><span>${displayDate(date)} · Изменения появятся в отчёте после одобрения</span></div><div id="hire-list">${workers.map((worker,i)=>`<div class="hire-row ${key==='hires'?'':'people-row'}"><span class="hire-index">${i+1}</span><input class="input hire-input" value="${esc(worker.fullName)}" placeholder="Фамилия Имя Отчество" aria-label="ФИО">${key==='hires'?`<input class="input hire-position" value="${esc(worker.position)}" placeholder="Должность" aria-label="Должность">`:''}<button class="remove-hire" data-i="${i}" aria-label="Удалить запись">×</button></div>`).join('')||'<div class="modal-empty">Список пуст. После одобрения запроса все записи из этой ячейки будут удалены.</div>'}</div><button id="add-hire" class="add-row-button">+ Добавить</button><div class="field"><label for="cell-correction-note">Причина корректировки <small>необязательно</small></label><textarea id="cell-correction-note" class="input" maxlength="1000" rows="3" placeholder="Например: забыли добавить кандидата или внесли ФИО с ошибкой">${esc(note)}</textarea><small class="correction-form-hint">До 1000 символов</small></div></div>`;
 const redraw=()=>{modalRoot.querySelector('.modal-body')!.innerHTML=body();wire()};
 const wire=()=>{modalRoot.querySelector<HTMLButtonElement>('#add-hire')!.onclick=()=>{read();workers.push({fullName:'',position:''});redraw();const inputs=modalRoot.querySelectorAll<HTMLInputElement>('.hire-input');inputs[inputs.length-1]?.focus()};modalRoot.querySelectorAll<HTMLButtonElement>('.remove-hire').forEach(button=>button.onclick=()=>{read();workers.splice(Number(button.dataset.i),1);redraw()})};
 showModal('Запрос на корректировку',body(),async()=>{
  if(sending)return;read();note=note.trim();
  const cleaned=workers.map(worker=>({fullName:worker.fullName.trim(),position:worker.position.trim()})).filter(worker=>worker.fullName);
  const values=JSON.parse(JSON.stringify(baseline)) as CorrectionValues;
  if(key==='hires')values.hiredWorkers=cleaned;else{values.people[peopleFields[key].category]=cleaned.map(worker=>worker.fullName);values[key]=cleaned.length}
  if(JSON.stringify(values)===JSON.stringify(baseline)){toast('Измените список перед отправкой',true);return}
  const category=key==='hires'?'hired_workers':peopleFields[key].category;
  const originals=key==='hires'?baseline.hiredWorkers:(baseline.people[peopleFields[key].category]||[]).map(fullName=>({fullName,position:''}));
  const edits:(CandidateCorrectionDiff&{category:string})[]=[];
  originals.forEach((before,origin)=>{const worker=workers.find(item=>item.origin===origin),after=worker?{fullName:worker.fullName.trim(),position:worker.position.trim()}:undefined;if(!after?.fullName)edits.push({category,kind:'removed',before});else if(before.fullName!==after.fullName||before.position!==after.position)edits.push({category,kind:'changed',before,after})});
  workers.filter(worker=>worker.origin===undefined&&worker.fullName.trim()).forEach(worker=>edits.push({category,kind:'added',after:{fullName:worker.fullName.trim(),position:worker.position.trim()}}));
  const button=modalRoot.querySelector<HTMLButtonElement>('.save')!;sending=true;button.disabled=true;button.textContent='Отправка…';
  try{await api('/api/correction-requests',{method:'POST',body:JSON.stringify({reportDate:date,reportType,note,rows:[{rowId:row.id,values,edits}]})});closeModal();toast('Запрос отправлен. Статус — в разделе «Запросы на корректировку»')}
  catch(error){sending=false;button.disabled=false;button.textContent='Отправить запрос';toast((error as Error).message,true)}
 },()=>{wire();modalRoot.querySelector('.modal')!.classList.add('cell-correction-modal');modalRoot.querySelector<HTMLButtonElement>('.save')!.textContent='Отправить запрос';const back=modalRoot.querySelector<HTMLButtonElement>('.cancel')!;back.textContent='Назад к списку';back.onclick=()=>{if(sending)return;read();showCellCorrectionList(row,key,()=>showCellCorrectionEditor(row,key,{workers,note,baseline}))}})
}
function showCorrectionRequestModal(){reportDate=previousBusinessDay();currentPage='report';history.pushState(null,'',pageUrl(currentPage));drawNav();route()}

function correctionDetailsBody(request:CorrectionRequest){return `<div class="correction-detail"><div class="correction-detail-context"><div><small>Сотрудник</small><b>${esc(request.employeeName)}</b></div><div><small>Отчёт</small><b>${esc(correctionReportType[request.reportType])}</b></div><div><small>Дата</small><b>${displayDate(request.reportDate)}</b></div></div><div class="correction-detail-note"><small>Причина</small><p>${esc(request.note||"Без примечания")}</p></div>${request.changes.map(change=>{const diffs=correctionDiffs(change),candidates=correctionCandidateDetails(change);return `<section class="correction-diff-unit"><h3>${esc(change.unitName)}</h3>${diffs.length?`<div class="correction-diff-list">${diffs.map(diff=>`<div><span>${esc(diff.label)}</span><del>${diff.before}</del><i>→</i><ins>${diff.after}</ins></div>`).join('')}</div>`:''}${candidates||(!diffs.length?'<p>Изменений в списках нет</p>':'')}</section>`}).join('')}</div>`}
function showCorrectionDetails(request:CorrectionRequest){showInfoModal(`Изменения · ${displayDate(request.reportDate)}`,correctionDetailsBody(request))}

function renderCorrectionAdmin(requests:CorrectionRequest[]){
 setHeader('Запросы на корректировку','Рассмотрение запросов сотрудников');
 const rows=requests.map(request=>`<tr data-status="${request.status}" data-search="${esc((request.employeeName+' '+request.username+' '+request.note+' '+request.reportDate).toLowerCase())}"><td><div class="correction-person"><span>${esc(request.employeeName.split(/\s+/).slice(0,2).map(part=>part[0]).join('').toUpperCase())}</span><div><b>${esc(request.employeeName)}</b><small>${esc(request.username)}</small></div></div></td><td><b class="correction-table-date">${displayDate(request.reportDate)}</b><small class="correction-created">${esc(correctionReportType[request.reportType])}</small></td><td><p class="correction-note">${esc(request.note||"Без примечания")}</p><small class="correction-request-summary">${esc(correctionSummary(request))}</small>${request.reviewNote?`<small class="correction-admin-note">Ответ: ${esc(request.reviewNote)}</small>`:''}</td><td>${correctionStatusBadge(request)}</td><td class="correction-table-actions">${request.status==='pending'?`<button class="btn btn-primary inspect-correction" data-id="${request.id}">Проверить</button><button class="btn btn-danger reject-correction" data-id="${request.id}" data-name="${esc(request.employeeName)}">Отказать</button>`:`<button class="btn btn-outline view-correction" data-id="${request.id}">Детали</button>`}</td></tr>`).join('');
 content.innerHTML=`<div class="correction-page admin-corrections"><section class="correction-admin-head"><div><span class="correction-eyebrow">Центр запросов</span><h2>Корректировки отчётов</h2><p>Проверьте разницу «было → станет». При одобрении изменения сразу применяются к отчёту без выдачи доступа сотруднику.</p></div>${correctionStats(requests)}</section><section class="card admin-card correction-admin-card"><div class="card-head"><div class="correction-filters" role="tablist"><button class="is-active" data-status="pending">Ожидают <b>${requests.filter(x=>x.status==='pending').length}</b></button><button data-status="all">Все</button><button data-status="approved">Одобрено</button><button data-status="rejected">Отклонено</button></div><label class="table-search">${icons.search}<input id="correction-search" type="search" autocomplete="off" placeholder="Сотрудник, дата или причина"></label></div><div class="table-scroll"><table class="data-table correction-table"><thead><tr><th>Сотрудник</th><th>Отчёт и дата</th><th>Причина и изменения</th><th>Статус</th><th class="actions-col">Решение</th></tr></thead><tbody>${rows}</tbody></table></div><div class="filter-empty correction-filter-empty" hidden>По выбранному фильтру запросов нет</div></section></div>`;
 const search=document.querySelector<HTMLInputElement>('#correction-search')!,filterButtons=[...document.querySelectorAll<HTMLButtonElement>('.correction-filters button')];let selectedStatus='pending';
 const apply=()=>{const query=search.value.trim().toLowerCase();let visible=0;document.querySelectorAll<HTMLTableRowElement>('.correction-table tbody tr').forEach(row=>{const show=(selectedStatus==='all'||row.dataset.status===selectedStatus)&&(!query||(row.dataset.search||'').includes(query));row.hidden=!show;if(show)visible++});document.querySelector<HTMLElement>('.correction-filter-empty')!.hidden=visible>0};
 filterButtons.forEach(button=>button.onclick=()=>{selectedStatus=button.dataset.status!;filterButtons.forEach(item=>item.classList.toggle('is-active',item===button));apply()});search.oninput=apply;apply();
 document.querySelectorAll<HTMLButtonElement>('.inspect-correction').forEach(button=>button.onclick=()=>showCorrectionReviewModal(requests.find(request=>request.id===button.dataset.id)!));
 document.querySelectorAll<HTMLButtonElement>('.reject-correction').forEach(button=>button.onclick=()=>showRejectCorrectionModal(button.dataset.id!,button.dataset.name||'сотрудника'))
 document.querySelectorAll<HTMLButtonElement>('.view-correction').forEach(button=>button.onclick=()=>showCorrectionDetails(requests.find(request=>request.id===button.dataset.id)!))
}

function showCorrectionReviewModal(request:CorrectionRequest){showModal('Проверка изменений',correctionDetailsBody(request),async()=>{const button=document.querySelector<HTMLButtonElement>('.modal .save')!;button.dataset.id=request.id;await reviewCorrectionRequest(button,'approve')},()=>{const modal=document.querySelector<HTMLElement>('.modal')!;modal.classList.add('correction-review-modal');const save=modal.querySelector<HTMLButtonElement>('.save')!;save.textContent='Применить изменения'})}

async function reviewCorrectionRequest(button:HTMLButtonElement,action:'approve'|'reject',reviewNote=''){
 button.disabled=true;try{await api(`/api/correction-requests/${button.dataset.id}`,{method:'PUT',body:JSON.stringify({action,reviewNote})});closeModal();toast(action==='approve'?'Изменения применены к отчёту':'Запрос отклонён');await correctionRequestsPage()}catch(error){button.disabled=false;toast((error as Error).message,true)}
}

function showRejectCorrectionModal(id:string,name:string){
 showModal('Отклонить запрос',`<div class="correction-form reject-form"><div class="correction-form-intro reject"><span>!</span><div><b>${esc(name)}</b><small>Сотрудник увидит причину отказа в истории запросов</small></div></div><div class="field"><label>Причина отказа</label><textarea id="correction-review-note" class="input" maxlength="1000" rows="4" placeholder="Укажите, почему корректировка не может быть выполнена"></textarea></div></div>`,async()=>{const note=(document.querySelector('#correction-review-note') as HTMLTextAreaElement).value.trim();if(note.length<3){toast('Укажите причину отказа минимум в 3 символах',true);return}const button=document.querySelector<HTMLButtonElement>('.modal .save')!;button.dataset.id=id;await reviewCorrectionRequest(button,'reject',note)},()=>{const save=document.querySelector<HTMLButtonElement>('.modal .save')!;save.textContent='Отклонить запрос';save.classList.remove('btn-primary');save.classList.add('btn-danger')})
}

async function historyPage(){setHeader('История отчётов','Архив и выгрузка отчётов за период');const from=new Date(Date.now()-30*86400000).toISOString().slice(0,10),to=today();content.innerHTML=`<div class="toolbar"><div class="field"><label>С даты</label><input id="from" class="input" type="date" value="${from}"></div><div class="field"><label>По дату</label><input id="to" class="input" type="date" value="${to}"></div><button id="find" class="btn btn-primary">Показать</button><div class="spacer"></div><button id="period-export" class="btn btn-outline">Выгрузить период</button></div><div class="card"><div id="history-list"></div></div>`;const load=async()=>{const f=(document.querySelector('#from') as HTMLInputElement).value,t=(document.querySelector('#to') as HTMLInputElement).value,rows=await api<any[]>(`/api/reports/history?from=${f}&to=${t}`);document.querySelector('#history-list')!.innerHTML=rows.length?`<table class="data-table"><thead><tr><th>Дата</th><th>Статус</th><th>Порог</th><th>Приглашено</th><th>Стажёры</th><th>Принято</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr><td>${x.date}</td><td><span class="status-pill ${x.status}">${x.status==='completed'?'Завершён':'Черновик'}</span></td><td>${x.threshold}</td><td>${x.invited}</td><td>${x.interns}</td><td>${x.hires}</td><td><button class="btn btn-outline open-report" data-date="${x.date}">Открыть</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty">За выбранный период отчётов нет</div>';document.querySelectorAll<HTMLButtonElement>('.open-report').forEach(b=>b.onclick=()=>{reportDate=b.dataset.date!;currentPage='report';history.pushState(null,'',pageUrl(currentPage));drawNav();route()})};document.querySelector<HTMLButtonElement>('#find')!.onclick=load;document.querySelector<HTMLButtonElement>('#period-export')!.onclick=()=>download(`/api/reports/export?from=${(document.querySelector('#from') as HTMLInputElement).value}&to=${(document.querySelector('#to') as HTMLInputElement).value}`);await load()}

async function employeesPage(){setHeader('Сотрудники','Справочник сотрудников и массовый импорт');const rows=await api<Employee[]>('/api/employees');content.innerHTML=`<div class="card"><div class="card-head"><h2>Сотрудники <span class="muted">${rows.length}</span></h2><div><button id="template" class="btn btn-outline">Скачать шаблон</button> <button id="import" class="btn btn-outline">Импорт XLSX</button> <button id="new-employee" class="btn btn-primary">+ Добавить</button></div></div><table class="data-table"><thead><tr><th>Фамилия</th><th>Имя</th><th>Отчество</th><th>Статус</th><th></th></tr></thead><tbody>${rows.map(e=>`<tr><td>${esc(e.lastName)}</td><td>${esc(e.firstName)}</td><td>${esc(e.middleName)}</td><td>${e.active?'Активен':'Архив'}</td><td><button class="btn btn-outline edit-employee" data-id="${e.id}">Изменить</button></td></tr>`).join('')}</tbody></table>${rows.length?'':'<div class="empty">Добавьте первого сотрудника</div>'}</div>`;document.querySelector<HTMLButtonElement>('#template')!.onclick=()=>download('/api/employees/template');document.querySelector<HTMLButtonElement>('#import')!.onclick=importModal;document.querySelector<HTMLButtonElement>('#new-employee')!.onclick=()=>employeeModal();document.querySelectorAll<HTMLButtonElement>('.edit-employee').forEach(b=>b.onclick=()=>employeeModal(rows.find(x=>x.id===b.dataset.id)))}
function employeeModal(e?:Employee){showModal(e?'Редактировать сотрудника':'Новый сотрудник',`<div class="grid-form"><div class="field"><label>Фамилия</label><input id="last" class="input" value="${esc(e?.lastName||'')}"></div><div class="field"><label>Имя</label><input id="first" class="input" value="${esc(e?.firstName||'')}"></div><div class="field"><label>Отчество</label><input id="middle" class="input" value="${esc(e?.middleName||'')}"></div></div>`,async()=>{const x={lastName:(document.querySelector('#last') as HTMLInputElement).value,firstName:(document.querySelector('#first') as HTMLInputElement).value,middleName:(document.querySelector('#middle') as HTMLInputElement).value,active:e?.active??true};await api(e?`/api/employees/${e.id}`:'/api/employees',{method:e?'PUT':'POST',body:JSON.stringify(x)});closeModal();toast('Сотрудник сохранён');employeesPage()})}
function importModal(){showModal('Импорт сотрудников',`<p class="muted">XLSX должен содержать строго три колонки: <b>Имя, Фамилия, Отчество</b>.</p><input id="import-file" class="input" type="file" accept=".xlsx"><div id="import-progress" style="display:none;margin-top:18px"><div class="progress"><span style="width:0"></span></div><p id="progress-text"></p><div class="error-list"></div></div>`,async()=>{const file=(document.querySelector('#import-file') as HTMLInputElement).files?.[0];if(!file){toast('Выберите файл',true);return}const fd=new FormData();fd.append('file',file);const x=await api<{id:string}>('/api/imports/employees',{method:'POST',body:fd});const box=document.querySelector<HTMLElement>('#import-progress')!;box.style.display='block';const ws=new WebSocket(`${location.protocol==='https:'?'wss':'ws'}://${location.host}/ws/imports/${x.id}`);ws.onmessage=ev=>{const p=JSON.parse(ev.data),percent=p.total?Math.round(p.processed*100/p.total):0;(box.querySelector('.progress span') as HTMLElement).style.width=percent+'%';box.querySelector('#progress-text')!.textContent=`Обработано ${p.processed} из ${p.total}, импортировано ${p.imported}`;box.querySelector('.error-list')!.innerHTML=(p.errors||[]).map((e:any)=>`Строка ${e.row}: ${esc(e.message)}`).join('<br>');if(p.status==='completed'||p.status==='failed'){ws.close();toast(p.status==='completed'?'Импорт завершён':'Ошибка импорта',p.status==='failed')}};document.querySelector<HTMLButtonElement>('.modal .save')!.disabled=true})}

async function usersPage(){
 const rows=await api<User[]>('/api/users'),name=(u:User)=>[u.lastName,u.firstName,u.middleName].filter(Boolean).join(' ');
 setHeader('Пользователи','Сотрудники и роли');
 content.innerHTML=`<div class="card admin-card"><div class="card-head"><div class="list-heading"><h2>Пользователи</h2><span>${rows.length} активных учётных записей</span></div><div class="page-actions"><label class="table-search">${icons.search}<input id="user-search" type="search" autocomplete="off" value="" placeholder="Найти по ФИО или логину" aria-label="Поиск пользователей"></label><button id="new-user" class="btn btn-primary">+ Добавить сотрудника</button></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>ФИО</th><th>Логин</th><th>Роль</th><th>Планы РП</th><th>Планы ГО</th><th class="actions-col">Действия</th></tr></thead><tbody>${rows.map(u=>`<tr data-search="${esc((name(u)+' '+u.username).toLowerCase())}"><td class="primary-cell">${esc(name(u))}</td><td><span class="login-value">${esc(u.username)}</span></td><td><span class="role-badge ${u.role}">${u.role==='admin'?'Администратор':'Сотрудник'}</span></td><td>${u.role==='employee'?`<span class="plan-summary">Пригл. <b>${u.invitationPlan}</b> · Прин. <b>${u.plan}</b></span>`:'—'}</td><td>${u.role==='employee'?`<span class="plan-summary">Пригл. <b>${u.mainOfficeInvitationPlan}</b> · Прин. <b>${u.mainOfficePlan}</b></span>`:'—'}</td><td class="row-actions">${u.role==='employee'?`<button class="btn btn-outline edit-plans" data-id="${u.id}">Планы</button>`:''}<button class="btn btn-outline edit-user" data-id="${u.id}">Изменить</button><button class="btn btn-danger delete-user" data-id="${u.id}">Удалить</button></td></tr>`).join('')}</tbody></table></div>${rows.length?'':'<div class="empty">Добавьте первого сотрудника</div>'}<div class="filter-empty" hidden>По вашему запросу ничего не найдено</div></div>`;
 const search=document.querySelector<HTMLInputElement>('#user-search')!;search.oninput=()=>filterRows(search.value);
 document.querySelector<HTMLButtonElement>('#new-user')!.onclick=()=>userModal();
 document.querySelectorAll<HTMLButtonElement>('.edit-user').forEach(b=>b.onclick=()=>userModal(rows.find(x=>x.id===b.dataset.id)));
 document.querySelectorAll<HTMLButtonElement>('.edit-plans').forEach(b=>b.onclick=()=>candidatePlansModal(rows.find(x=>x.id===b.dataset.id)!));
 document.querySelectorAll<HTMLButtonElement>('.delete-user').forEach(b=>b.onclick=async()=>{const u=rows.find(x=>x.id===b.dataset.id)!;if(!confirm(`Удалить учётную запись ${u.username}? Восстановить сотрудника будет нельзя.`))return;try{await api(`/api/users/${u.id}`,{method:'DELETE'});toast('Сотрудник удалён');await usersPage()}catch(e){toast((e as Error).message,true)}})
}
async function exportPage(){const own=!manager();setHeader('Выгрузка',own?'Мои показатели за выбранный период':'Сводные показатели за выбранный период');const from=today(),to=today();content.innerHTML=`<div class="card export-panel"><div class="card-head"><h2>Выгрузка XLSX за период</h2></div><div class="panel-body"><div class="export-form"><div class="field"><label>Тип отчёта</label><select id="export-report-type" autocomplete="off"><option value="rp">РП</option><option value="main_office">ГО</option><option value="all">Все</option></select></div><div class="field"><label>Дата начала</label><input id="export-from" class="input" type="date" autocomplete="off" value="${from}"></div><div class="field"><label>Дата окончания</label><input id="export-to" class="input" type="date" autocomplete="off" value="${to}"></div></div><div class="export-note"><b>${own?'Только мои отчёты':'Сводный отчёт и сотрудники'}</b><span>${own?'В файл попадут только данные из отчётов, заполненных под вашей учётной записью.':'Каждый выбранный тип отчёта получает отдельный лист: сначала общая таблица, затем персональные таблицы сотрудников.'}</span></div><div class="export-note"><b>Принятые сотрудники и списки ФИО</b><span>Для РП и ГО создаются отдельные листы с принятыми сотрудниками, их должностями и детализацией кадровых показателей.</span></div></div><div class="panel-actions"><button id="download-period" class="btn btn-primary with-icon">${icons.download}<span>Скачать XLSX</span></button></div></div>`;document.querySelector<HTMLButtonElement>('#download-period')!.onclick=()=>{const start=(document.querySelector('#export-from') as HTMLInputElement).value,end=(document.querySelector('#export-to') as HTMLInputElement).value,reportType=(document.querySelector('#export-report-type') as HTMLSelectElement).value;if(!start||!end||start>end){toast('Укажите корректный период',true);return}download(`/api/reports/export?from=${encodeURIComponent(start)}&to=${encodeURIComponent(end)}&reportType=${encodeURIComponent(reportType)}`)}}
function userModal(u?:User){
 const canChooseRole=currentUser?.role==='superadmin',planSection=!u?`<section class="form-section candidate-plan-option" id="candidate-plan-option"><label class="plan-toggle"><input id="add-candidate-plans" type="checkbox"><span><b>Добавить планы кандидатов</b><small>Указать планы по приглашённым и принятым кандидатам для РП и ГО</small></span></label></section><div class="candidate-plans-panel" id="candidate-plans-panel" hidden>${candidatePlansFields()}</div>`:'';
 showModal(u?'Изменить пользователя':'Новый пользователь',`<div class="user-form"><section class="form-section"><div class="form-section-head"><b>Данные сотрудника</b><span>ФИО отображается в отчётах и подсказках таблицы</span></div><div class="person-grid"><div class="field"><label>Фамилия</label><input id="user-last" class="input" placeholder="Например, Иванов" value="${esc(u?.lastName||'')}"></div><div class="field"><label>Имя</label><input id="user-first" class="input" placeholder="Иван" value="${esc(u?.firstName||'')}"></div><div class="field"><label>Отчество</label><input id="user-middle" class="input" placeholder="Иванович" value="${esc(u?.middleName||'')}"></div></div></section><section class="form-section"><div class="form-section-head"><b>Доступ к системе</b><span>Логин должен быть уникальным, пароль — не короче 8 символов</span></div><div class="access-grid"><div class="field"><label>Логин</label><input id="user-login" class="input" autocomplete="off" value="${esc(u?.username||'')}"></div><div class="field"><label>${u?'Новый пароль':'Пароль'}</label><input id="user-password" class="input" type="password" autocomplete="new-password" placeholder="${u?'Оставьте пустым, чтобы не менять':'Минимум 8 символов'}"></div><div class="field"><label>Роль</label><select id="user-role" ${canChooseRole?'':'disabled'}><option value="employee">Сотрудник</option>${canChooseRole?'<option value="admin">Администратор</option>':''}</select></div></div></section>${planSection}</div>`,async()=>{const role=(document.querySelector('#user-role') as HTMLSelectElement).value,addPlans=!u&&role==='employee'&&(document.querySelector<HTMLInputElement>('#add-candidate-plans')?.checked||false),plans=addPlans?readCandidatePlans():null;if(plans&&!validCandidatePlans(plans)){toast('Заполните дату и укажите целые неотрицательные планы',true);return}const payload={lastName:(document.querySelector('#user-last') as HTMLInputElement).value,firstName:(document.querySelector('#user-first') as HTMLInputElement).value,middleName:(document.querySelector('#user-middle') as HTMLInputElement).value,username:(document.querySelector('#user-login') as HTMLInputElement).value,password:(document.querySelector('#user-password') as HTMLInputElement).value,role,active:true,plan:plans?.rpHired||0,planFrom:plans?.effectiveFrom||'',mainOfficePlan:plans?.mainOfficeHired||0,mainOfficePlanFrom:plans?.effectiveFrom||'',invitationPlan:plans?.rpInvited||0,mainOfficeInvitationPlan:plans?.mainOfficeInvited||0};try{await api(u?`/api/users/${u.id}`:'/api/users',{method:u?'PUT':'POST',body:JSON.stringify(payload)});closeModal();toast('Пользователь сохранён');adminUsers=[];await usersPage()}catch(e){toast((e as Error).message,true)}})
 if(!u){const toggle=document.querySelector<HTMLInputElement>('#add-candidate-plans')!,panel=document.querySelector<HTMLElement>('#candidate-plans-panel')!,option=document.querySelector<HTMLElement>('#candidate-plan-option')!,role=document.querySelector<HTMLSelectElement>('#user-role')!;toggle.onchange=()=>{panel.hidden=!toggle.checked};const syncRole=()=>{const employee=role.value==='employee';option.hidden=!employee;panel.hidden=!employee||!toggle.checked};role.addEventListener('change',syncRole);syncRole()}
}
function candidatePlansFields(u?:User){return `<section class="form-section candidate-plans-section"><div class="form-section-head candidate-plans-head"><div class="candidate-plans-copy"><b>Планы кандидатов</b><span>Отдельные значения для отчётов РП и ГО</span></div><div class="field plan-effective-date"><label>Действуют с</label><input id="candidate-plans-from" class="input" type="date" value="${today()}"></div></div><div class="candidate-plan-matrix"><div class="matrix-head"></div><div class="matrix-head">РП</div><div class="matrix-head">ГО</div><label><span>Приглашённые кандидаты</span></label><input id="plan-rp-invited" class="input" type="number" min="0" step="1" inputmode="numeric" value="${u?.invitationPlan||0}"><input id="plan-main-invited" class="input" type="number" min="0" step="1" inputmode="numeric" value="${u?.mainOfficeInvitationPlan||0}"><label><span>Принятые кандидаты</span></label><input id="plan-rp-hired" class="input" type="number" min="0" step="1" inputmode="numeric" value="${u?.plan||0}"><input id="plan-main-hired" class="input" type="number" min="0" step="1" inputmode="numeric" value="${u?.mainOfficePlan||0}"></div></section>`}
function readCandidatePlans(){return{effectiveFrom:(document.querySelector('#candidate-plans-from') as HTMLInputElement).value,rpInvited:Number((document.querySelector('#plan-rp-invited') as HTMLInputElement).value),rpHired:Number((document.querySelector('#plan-rp-hired') as HTMLInputElement).value),mainOfficeInvited:Number((document.querySelector('#plan-main-invited') as HTMLInputElement).value),mainOfficeHired:Number((document.querySelector('#plan-main-hired') as HTMLInputElement).value)}}
function validCandidatePlans(plans:ReturnType<typeof readCandidatePlans>){return !!plans.effectiveFrom&&[plans.rpInvited,plans.rpHired,plans.mainOfficeInvited,plans.mainOfficeHired].every(value=>Number.isInteger(value)&&value>=0)}
function candidatePlansModal(u:User){showModal(`Планы · ${[u.lastName,u.firstName].filter(Boolean).join(' ')}`,candidatePlansFields(u),async()=>{const plans=readCandidatePlans();if(!validCandidatePlans(plans)){toast('Заполните дату и укажите целые неотрицательные планы',true);return}await api(`/api/users/${u.id}/candidate-plans`,{method:'PUT',body:JSON.stringify(plans)});closeModal();toast('Планы сотрудника сохранены');await usersPage()})}
async function officesPage(){setHeader('РП','Отдельный справочник подразделений');const rows=await api<any[]>('/api/offices');content.innerHTML=`<div class="card admin-card"><div class="card-head"><div class="list-heading"><h2>РП</h2><span>${rows.filter(o=>o.active).length} активных · ${rows.filter(o=>!o.active).length} архивных</span></div><div class="page-actions"><select id="office-status" aria-label="Статус РП"><option value="active">Активные РП</option><option value="archived">Архивные РП</option><option value="all">Все РП</option></select><label class="table-search">${icons.search}<input id="office-search" type="search" placeholder="Найти РП" aria-label="Поиск РП"></label><button id="new-office" class="btn btn-primary">+ Добавить РП</button></div></div><div class="table-scroll"><table class="data-table office-table"><thead><tr><th class="order-col">Порядок</th><th>Название РП</th><th>Статус</th><th class="actions-col">Действия</th></tr></thead><tbody>${rows.map((o,i)=>`<tr data-id="${o.id}" data-active="${o.active?'true':'false'}" data-search="${esc(String(o.name).toLowerCase())}"><td><span class="drag-handle" draggable="true" aria-label="Перетащить РП"><i></i><span class="sort-value">${i+1}</span></span></td><td class="primary-cell">${esc(o.name)}</td><td><span class="state-badge ${o.active?'active':'inactive'}"><i></i>${o.active?'Активно':'Архив'}</span></td><td class="row-actions"><button class="btn btn-outline edit-office" data-id="${o.id}">${o.active?'Изменить':'Просмотреть / восстановить'}</button></td></tr>`).join('')}</tbody></table></div><div class="filter-empty" hidden>По выбранному фильтру ничего не найдено</div></div>`;const search=document.querySelector<HTMLInputElement>('#office-search')!,status=document.querySelector<HTMLSelectElement>('#office-status')!,apply=()=>{const query=search.value.trim().toLowerCase();let shown=0;content.querySelectorAll<HTMLTableRowElement>('.office-table tbody tr').forEach(row=>{const matchesStatus=status.value==='all'||(status.value==='active'&&row.dataset.active==='true')||(status.value==='archived'&&row.dataset.active==='false'),visible=matchesStatus&&(!query||(row.dataset.search||'').includes(query));row.hidden=!visible;if(visible)shown++});content.querySelector<HTMLElement>('.filter-empty')!.hidden=shown>0};search.oninput=apply;status.onchange=apply;apply();document.querySelector<HTMLButtonElement>('#new-office')!.onclick=()=>officeModal();document.querySelectorAll<HTMLButtonElement>('.edit-office').forEach(b=>b.onclick=()=>officeModal(rows.find(x=>x.id===b.dataset.id)));wireOfficeSorting()}
function wireOfficeSorting(){const tbody=content.querySelector<HTMLTableSectionElement>('.office-table tbody');if(!tbody)return;let dragged:HTMLTableRowElement|null=null;tbody.querySelectorAll<HTMLElement>('.drag-handle').forEach(handle=>{handle.ondragstart=e=>{dragged=handle.closest('tr');dragged?.classList.add('dragging');if(e.dataTransfer){e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',dragged?.dataset.id||'')}};handle.ondragend=()=>{dragged?.classList.remove('dragging');dragged=null;tbody.querySelectorAll('tr').forEach(row=>row.classList.remove('drag-over'))}});tbody.ondragover=e=>{if(!dragged)return;e.preventDefault();const target=(e.target as HTMLElement).closest<HTMLTableRowElement>('tr');if(!target||target===dragged)return;tbody.querySelectorAll('tr').forEach(row=>row.classList.remove('drag-over'));target.classList.add('drag-over');const after=e.clientY>target.getBoundingClientRect().top+target.offsetHeight/2;tbody.insertBefore(dragged,after?target.nextSibling:target)};tbody.ondrop=async e=>{if(!dragged)return;e.preventDefault();tbody.querySelectorAll('tr').forEach(row=>row.classList.remove('drag-over'));const ordered=[...tbody.querySelectorAll<HTMLTableRowElement>('tr')];ordered.forEach((row,i)=>{const number=row.querySelector<HTMLElement>('.sort-value');if(number)number.textContent=String(i+1)});try{await api('/api/offices/order',{method:'PUT',body:JSON.stringify({ids:ordered.map(row=>row.dataset.id)})});toast('Порядок РП сохранён')}catch(error){toast((error as Error).message,true);officesPage()}}}
function officeModal(o?:any){showModal(o?'Изменить РП':'Новое РП',`<div class="office-form"><div class="form-section-head"><b>Параметры РП</b><span>Архивное РП не добавляется в новые отчёты, но сохраняется в старых.</span></div><div class="field"><label>Название РП</label><input id="office-name" class="input" placeholder="Введите полное название" value="${esc(o?.name||'')}"></div>${o?`<label class="active-switch"><input id="office-active" type="checkbox" ${o.active?'checked':''}><span><b>РП активно</b><small>Отключите, чтобы перенести РП в архив</small></span></label>`:''}</div>`,async()=>{const x={name:(document.querySelector('#office-name') as HTMLInputElement).value,active:o?(document.querySelector('#office-active') as HTMLInputElement).checked:true};await api(o?`/api/offices/${o.id}`:'/api/offices',{method:o?'PUT':'POST',body:JSON.stringify(x)});closeModal();toast(x.active?'РП сохранено':'РП перенесено в архив');officesPage()})}
async function mainOfficesPage(){setHeader('Компании главного офиса','Отдельный справочник компаний');const rows=await api<any[]>('/api/main-offices');content.innerHTML=`<div class="card admin-card"><div class="card-head"><div class="list-heading"><h2>Компании</h2><span>${rows.filter(o=>o.active).length} активных · ${rows.filter(o=>!o.active).length} архивных</span></div><div class="page-actions"><select id="office-status" aria-label="Статус компании"><option value="active">Активные компании</option><option value="archived">Архивные компании</option><option value="all">Все компании</option></select><label class="table-search">${icons.search}<input id="office-search" type="search" placeholder="Найти компанию" aria-label="Поиск компаний"></label><button id="new-main-office" class="btn btn-primary">+ Добавить компанию</button></div></div><div class="table-scroll"><table class="data-table office-table"><thead><tr><th class="order-col">Порядок</th><th>Название компании</th><th>Статус</th><th class="actions-col">Действия</th></tr></thead><tbody>${rows.map((o,i)=>`<tr data-id="${o.id}" data-active="${o.active?'true':'false'}" data-search="${esc(String(o.name).toLowerCase())}"><td><span class="drag-handle" draggable="true" aria-label="Перетащить компанию"><i></i><span class="sort-value">${i+1}</span></span></td><td class="primary-cell">${esc(o.name)}</td><td><span class="state-badge ${o.active?'active':'inactive'}"><i></i>${o.active?'Активна':'Архив'}</span></td><td class="row-actions"><button class="btn btn-outline edit-main-office" data-id="${o.id}">${o.active?'Изменить':'Просмотреть / восстановить'}</button></td></tr>`).join('')}</tbody></table></div><div class="filter-empty" hidden>По выбранному фильтру ничего не найдено</div></div>`;const search=document.querySelector<HTMLInputElement>('#office-search')!,status=document.querySelector<HTMLSelectElement>('#office-status')!,apply=()=>{const query=search.value.trim().toLowerCase();let shown=0;content.querySelectorAll<HTMLTableRowElement>('.office-table tbody tr').forEach(row=>{const matchesStatus=status.value==='all'||(status.value==='active'&&row.dataset.active==='true')||(status.value==='archived'&&row.dataset.active==='false'),visible=matchesStatus&&(!query||(row.dataset.search||'').includes(query));row.hidden=!visible;if(visible)shown++});content.querySelector<HTMLElement>('.filter-empty')!.hidden=shown>0};search.oninput=apply;status.onchange=apply;apply();document.querySelector<HTMLButtonElement>('#new-main-office')!.onclick=()=>mainOfficeModal();document.querySelectorAll<HTMLButtonElement>('.edit-main-office').forEach(button=>button.onclick=()=>mainOfficeModal(rows.find(x=>x.id===button.dataset.id)));wireMainOfficeSorting()}
function wireMainOfficeSorting(){const tbody=content.querySelector<HTMLTableSectionElement>('.office-table tbody');if(!tbody)return;let dragged:HTMLTableRowElement|null=null;tbody.querySelectorAll<HTMLElement>('.drag-handle').forEach(handle=>{handle.ondragstart=e=>{dragged=handle.closest('tr');dragged?.classList.add('dragging');if(e.dataTransfer){e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',dragged?.dataset.id||'')}};handle.ondragend=()=>{dragged?.classList.remove('dragging');dragged=null;tbody.querySelectorAll('tr').forEach(row=>row.classList.remove('drag-over'))}});tbody.ondragover=e=>{if(!dragged)return;e.preventDefault();const target=(e.target as HTMLElement).closest<HTMLTableRowElement>('tr');if(!target||target===dragged)return;tbody.querySelectorAll('tr').forEach(row=>row.classList.remove('drag-over'));target.classList.add('drag-over');const after=e.clientY>target.getBoundingClientRect().top+target.offsetHeight/2;tbody.insertBefore(dragged,after?target.nextSibling:target)};tbody.ondrop=async e=>{if(!dragged)return;e.preventDefault();const ordered=[...tbody.querySelectorAll<HTMLTableRowElement>('tr')];ordered.forEach((row,i)=>{const number=row.querySelector<HTMLElement>('.sort-value');if(number)number.textContent=String(i+1)});try{await api('/api/main-offices/order',{method:'PUT',body:JSON.stringify({ids:ordered.map(row=>row.dataset.id)})});toast('Порядок компаний сохранён')}catch(error){toast((error as Error).message,true);mainOfficesPage()}}}
function mainOfficeModal(o?:any){showModal(o?'Изменить компанию':'Новая компания',`<div class="office-form"><div class="form-section-head"><b>Параметры компании</b><span>Архивная компания не добавляется в новые отчёты, но сохраняется в старых.</span></div><div class="field"><label>Название компании</label><input id="main-office-name" class="input" placeholder="Введите название компании" value="${esc(o?.name||'')}"></div>${o?`<label class="active-switch"><input id="main-office-active" type="checkbox" ${o.active?'checked':''}><span><b>Компания активна</b><small>Отключите, чтобы перенести компанию в архив</small></span></label>`:''}</div>`,async()=>{const x={name:(document.querySelector('#main-office-name') as HTMLInputElement).value,active:o?(document.querySelector('#main-office-active') as HTMLInputElement).checked:true};await api(o?`/api/main-offices/${o.id}`:'/api/main-offices',{method:o?'PUT':'POST',body:JSON.stringify(x)});closeModal();toast(x.active?'Компания сохранена':'Компания перенесена в архив');mainOfficesPage()})}
async function importsPage(){setHeader('Импорты','История фоновых операций');const rows=await api<any[]>('/api/imports');content.innerHTML=`<div class="card"><table class="data-table"><thead><tr><th>Дата</th><th>Файл</th><th>Статус</th><th>Прогресс</th><th>Импортировано</th><th>Ошибки</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${new Date(x.createdAt).toLocaleString('ru')}</td><td>${esc(x.fileName)}</td><td>${statusRu(x.status)}</td><td>${x.processedRows} / ${x.totalRows}</td><td>${x.importedRows}</td><td>${(x.errors||[]).length}</td></tr>`).join('')}</tbody></table>${rows.length?'':'<div class="empty">Импортов пока нет</div>'}</div>`}
function statusRu(s:string){return({queued:'В очереди',processing:'Обработка',completed:'Завершён',failed:'Ошибка'} as any)[s]||s}
function filterRows(query:string){const value=query.trim().toLowerCase();let shown=0;content.querySelectorAll<HTMLTableRowElement>('.data-table tbody tr').forEach(row=>{const visible=!value||(row.dataset.search||'').includes(value);row.hidden=!visible;if(visible)shown++});const empty=content.querySelector<HTMLElement>('.filter-empty');if(empty)empty.hidden=shown>0}
async function auditPage(){setHeader('Журнал действий','Последние изменения в системе');const rows=await api<any[]>('/api/audit');content.innerHTML=`<div class="card"><table class="data-table"><thead><tr><th>Дата и время</th><th>Пользователь</th><th>Действие</th><th>Объект</th><th>Идентификатор</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${new Date(x.createdAt).toLocaleString('ru')}</td><td>${esc(x.actor)}</td><td>${esc(x.action)}</td><td>${esc(x.entityType)}</td><td class="muted">${esc(x.entityId)}</td></tr>`).join('')}</tbody></table>${rows.length?'':'<div class="empty">Событий пока нет</div>'}</div>`}

document.addEventListener('fullscreenchange',()=>{if(!document.fullscreenElement)document.body.classList.remove('table-fullscreen')});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')scheduleDebtsterRefresh();else stopDebtsterRefresh()});
window.addEventListener('resize',()=>{closeDatePicker();if((currentPage==='report'||currentPage==='main-report')&&!hasCustomColumnWidths())applyColumnWidths()});
window.addEventListener('beforeunload',e=>{if(dirtyRows.size){e.preventDefault();e.returnValue='Есть несохранённые изменения'}});
window.addEventListener('popstate',()=>{if(!currentUser)return;const requestedPage=pageFromLocation();currentPage=pages.some(([id])=>id===requestedPage)?requestedPage:'report';reportDate=dateFromLocation();history.replaceState(null,'',pageUrl(currentPage));drawNav();route()});
document.querySelector<HTMLButtonElement>('#logout')!.onclick=async()=>{await api('/api/auth/logout',{method:'POST',body:'{}'});stopDebtsterRefresh();currentUser=null;showLogin()};
function configureUser(){if(!currentUser)return;const exportNav=['exports',icons.download,'Выгрузка'];pages=manager()?[...reportPage,exportNav,['users',icons.employees,'Пользователи'],['main-offices',icons.mainOffice,'ГО']]:[...reportPage,exportNav];const display=[currentUser.lastName,currentUser.firstName,currentUser.middleName].filter(Boolean).join(' ')||currentUser.username;document.querySelector('#profile-name')!.textContent=display;document.querySelector('#profile-role')!.textContent=currentUser.role==='superadmin'?'Суперадминистратор':currentUser.role==='admin'?'Администратор':'Сотрудник';document.querySelector('#profile-avatar')!.textContent=((currentUser.firstName?.[0]||'')+(currentUser.lastName?.[0]||currentUser.username[0]||'')).toUpperCase();reportDate=pageWasReloaded()?businessToday():dateFromLocation();const requestedPage=pageFromLocation();currentPage=pages.some(([id])=>id===requestedPage)?requestedPage:'report';selectedEmployee='';adminUsers=[];history.replaceState(null,'',pageUrl(currentPage));drawNav();route()}
function showLogin(message=''){document.body.classList.add('logged-out');modalRoot.innerHTML=`<div class="login-screen"><form class="login-card" id="login-form"><div class="login-brand"><span class="brand-mark">HR</span><div><strong>HR Daily</strong></div></div><div class="login-copy"><h1>Вход в систему</h1><p>Введите логин и пароль учётной записи</p></div><div class="field"><label>Логин</label><input id="login-name" class="input" autocomplete="username" autofocus></div><div class="field"><label>Пароль</label><input id="login-password" class="input" type="password" autocomplete="current-password"></div><div id="login-error" class="login-error">${esc(message)}</div><button class="btn btn-primary login-submit" type="submit">Войти</button></form></div>`;document.querySelector<HTMLFormElement>('#login-form')!.onsubmit=async e=>{e.preventDefault();const button=document.querySelector<HTMLButtonElement>('.login-submit')!;button.disabled=true;button.textContent='Вход...';try{currentUser=await api<User>('/api/auth/login',{method:'POST',body:JSON.stringify({username:(document.querySelector('#login-name') as HTMLInputElement).value,password:(document.querySelector('#login-password') as HTMLInputElement).value})});modalRoot.innerHTML='';document.body.classList.remove('logged-out');configureUser()}catch(err){document.querySelector('#login-error')!.textContent=(err as Error).message;button.disabled=false;button.textContent='Войти'}};requestAnimationFrame(()=>document.querySelector<HTMLInputElement>('#login-name')?.focus())}
async function init(){try{currentUser=await api<User>('/api/auth/me');document.body.classList.remove('logged-out');configureUser()}catch{showLogin()}}
init();
